"""Revalidate whole files previously represented by scattered function lessons."""
ROWS=[]


def add(path,title,intro,principle,use,sections,questions):
    ROWS.append(dict(path=path,title=title,intro=intro,principle=principle,use=use,
                     area='비트 알고리즘 · 병렬 합산·정렬',sections=sections,questions=questions))


add('lib/bitrev.c','비트 반전 표 전체: 256개 순열과 아키텍처 대체',
    '바이트 안의 비트 순서를 뒤집는 모든 경우를 표로 저장합니다. 기존 함수별 설명과 별도로 파일 전체를 다시 확인합니다.',
    'CONFIG_HAVE_ARCH_BITREVERSE가 없을 때만 byte_rev_table[256]을 정의합니다. 입력의 비트 i가 출력의 비트 7-i로 이동하는 순열이며 표 자체는 const u8입니다.',
    '표는 아키텍처 전용 비트 반전 구현이 없는 경로에서 헤더 helper가 사용합니다. bit reversal은 비트의 0/1 값을 뒤집는 NOT 연산과 다르고, 한 바이트 안에서는 바이트 엔디언 교환과도 다릅니다.',
    [('파일 전체','SPDX 다음 #ifndef가 include·모듈 정보·표·GPL export 전체를 감쌉니다. types.h는 u8, module.h는 메타데이터 및 export, bitrev.h는 선언과 helper 관계를 제공합니다. 이 파일 안에 별도 C 함수 본문은 없습니다.'),
     ('전체 표의 규칙','tab[0]=0,tab[1]=0x80,tab[0x12]=0x48,tab[255]=255입니다. 0x12=00010010₂를 뒤에서 읽으면 01001000₂=0x48입니다. 같은 순열을 두 번 적용하면 원래 값으로 돌아오므로 tab[tab[x]]=x가 모든 256개 입력에 성립합니다.'),
     ('데이터와 코드의 절충','256바이트를 사용해 바이트별 lookup을 O(1)로 수행합니다. 조회 인덱스가 u8이면 0..255 범위입니다. 아키텍처 기능이 있을 때는 이 데이터 파일의 정의가 빠질 수 있으므로 모든 빌드에 이 표가 존재한다고 가정하지 않습니다.'),
     ('CS 연결','순열의 역함수, 고정 폭 비트 표현, 데이터 기반 최적화, 빌드 시 다형성을 연결합니다. 반전은 1의 개수를 바꾸지 않으며 암호화나 인증 기능이 아닙니다. 표의 전 원소를 독립 비트 루프로 재구성해 비교할 수 있습니다.')],
    [('0x12의 8비트 역순 값은?', '0x48', '비트 NOT인 0xED', '00010010을 역순으로 읽으면 01001000입니다. NOT은 위치를 그대로 두고 각 비트 값을 바꾸는 다른 연산입니다.'),
     ('표 반전을 두 번 적용하면?', '원래 바이트로 돌아온다', '항상 0이 된다', 'i→7-i를 두 번 적용하면 7-(7-i)=i입니다. 순열 자체가 자기 역함수입니다.'),
     ('CONFIG_HAVE_ARCH_BITREVERSE가 있는 빌드에도 이 파일이 표를 정의하는가?', '아니다. 조건부 블록 전체가 제외된다', '그렇다. 아키텍처 경로와 표가 항상 중복된다', '#ifndef가 파일의 실질적 정의 전체를 감쌉니다. 헤더에서는 대신 아키텍처 helper를 선택합니다.')])

add('include/linux/bitrev.h','비트 반전 헤더 전체: 상수 경로·표 경로·바이트별 반전',
    '같은 결과를 만드는 여러 구현을 고르는 헤더입니다. 특히 전체 32비트 반전과 바이트 순서를 유지하는 반전을 구분합니다.',
    '아키텍처 기능이 있으면 __bitrev8/16/32를 아키텍처 helper에 연결합니다. 없으면 바이트 표를 조회하고 16·32비트를 작은 단위 반전과 위치 교환으로 조합합니다. 공개 bitrev 매크로들은 임시 변수와 __builtin_constant_p로 상수 계산 경로 또는 실행 경로를 선택합니다.',
    'bitrev32는 32비트 전체의 순서를 뒤집습니다. bitrev8x4는 네 바이트 각각의 비트만 뒤집고 바이트 순서는 유지합니다. 동적 8x4 경로는 swab32 후 전체 bitrev32를 수행하므로 사용 문맥에서 swab32도 사용 가능해야 합니다.',
    [('헤더의 앞부분 전체','SPDX·가드·types.h 포함 뒤 CONFIG_HAVE_ARCH_BITREVERSE 분기가 있습니다. 전용 경로는 asm/bitrev.h를 포함하고 세 이름을 별칭으로 연결합니다. fallback은 extern byte_rev_table과 세 inline helper를 정의합니다. 16비트는 낮은 바이트를 반전해 높은 자리로, 높은 바이트를 반전해 낮은 자리로 옮깁니다. 32비트도 같은 방식으로 16비트 두 조각을 처리합니다.'),
     ('상수 반전 단계','__constant_bitrev32는 16비트 반쪽 교환→바이트 교환→4비트 묶음 교환→2비트 교환→인접 비트 교환입니다. 16비트와 8비트 버전은 필요한 작은 단계부터 시작합니다. 마스크는 서로 섞이면 안 되는 묶음들을 골라 이동시키며 OR로 합칩니다. 고정 폭 임시 형식에 저장해 해당 폭의 결과를 유지합니다.'),
     ('8x4의 차이','__constant_bitrev8x4는 바이트 순서를 바꾸는 16·8비트 교환 단계를 생략하고 4·2·1비트 교환만 수행합니다. 입력 0x01020408은 바이트별로 0x80402010이 됩니다. 전체 bitrev32는 0x10204080입니다. 동적 __bitrev8x4는 swab32로 미리 바이트 순서를 바꾼 뒤 전체 반전하여 같은 바이트별 결과를 얻습니다.'),
     ('공개 매크로와 평가','bitrev8/16/32/8x4 각각은 x를 해당 폭의 지역 __x에 먼저 담습니다. 원래 인자 식을 한 번 평가한 뒤 그 값을 상수 판단과 선택된 경로에 전달합니다. __builtin_constant_p는 컴파일러가 상수로 판단할 수 있는지를 묻는 확장 기능이며 런타임 입력이 실제로 항상 같은 값이라는 증명이 아닙니다.'),
     ('CS 연결과 검토 범위','고정 폭 분할정복 순열, SWAR식 마스크 연산, 컴파일 시 최적화와 대체 구현 선택을 연결합니다. 이 헤더 전체의 선택·조합 로직을 설명하지만 각 아키텍처 명령 구현의 정확성까지 이 파일만으로 검증한 것으로 세지는 않습니다.')],
    [('0x01020408에 bitrev8x4를 적용하면?', '0x80402010', '0x10204080', '각 바이트 01,02,04,08은 80,40,20,10으로 변하고 바이트 위치는 유지됩니다. 후자는 전체 32비트 역순 결과입니다.'),
     ('상수 bitrev8x4가 전체 bitrev32와 달리 생략하는 단계는?', '바이트 순서를 바꾸는 큰 묶음 교환', '각 바이트 내부의 인접 비트 교환', '8x4는 바이트 위치를 유지해야 하므로 16비트 반쪽·8비트 바이트 교환을 하지 않습니다. 내부 4·2·1비트 교환은 필요합니다.'),
     ('공개 bitrev 매크로가 x를 임시 변수에 담는 이유 중 하나는?', '원래 인자 식을 반복 평가하지 않으려는 것', 'x의 원본 메모리를 자동으로 수정하려는 것', 'u32 __x=x 등의 초기화가 원래 인자 평가 지점입니다. 이후에는 지역 값을 사용하며 호출자 변수에 대입하는 매크로가 아닙니다.')])

add('lib/hweight.c','Hamming weight 전체: 마스크로 작은 합을 병렬 계산하기',
    '비트가 1인 개수를 하나씩 반복하지 않고 작은 묶음의 합으로 누적합니다.',
    '__sw_hweight8/16/32/64 네 함수가 해당 폭의 1비트 수를 계산합니다. 0x55...로 2비트 묶음 수를 만들고 0x33...으로 4비트 묶음을 합치며 0x0f...로 바이트별 합을 만듭니다. 32·64비트는 설정에 따라 곱셈 또는 추가 이동·덧셈으로 전체 합을 얻습니다.',
    '대상 폭에 맞는 값을 전달하고 반환값은 0..N의 개수라는 점을 기억합니다. BITS_PER_LONG==32인 64비트 함수는 상·하위 32비트의 결과를 더합니다. 실행 분기는 커널 빌드 설정에 의해 정해집니다.',
    [('파일 전체 구성','SPDX, export/bitops/asm types 헤더, 네 함수와 각 EXPORT_SYMBOL이 전부입니다. 8·16비트 함수는 단일 구현이며 32비트와 64비트의 빠른 곱셈 경로가 CONFIG_ARCH_HAS_FAST_MULTIPLIER로 구분됩니다. 64비트 함수에는 BITS_PER_LONG의 32/64 분기도 있습니다.'),
     ('2비트와 4비트 묶음','w-((w>>1)&0x55...)는 각 두 비트 00,01,10,11을 각각 개수 0,1,1,2로 바꿉니다. 이 두 비트 결과들을 0x33... 마스크와 이동으로 합치면 각 네 비트 안의 개수가 됩니다. 작은 묶음에 필요한 값 범위가 확보되어 인접 묶음이 섞이지 않도록 설계된 연산입니다.'),
     ('바이트 합에서 전체 합으로','(res+(res>>4))&0x0f...는 바이트마다 0..8의 합을 남깁니다. 빠른 곱셈 경로의 0x01010101 또는 64비트 대응 상수는 바이트 합을 높은 바이트로 누적하고 오른쪽 이동으로 결과를 고릅니다. 다른 경로는 8·16·32비트 이동 덧셈과 마지막 마스크로 전체 개수를 모읍니다.'),
     ('숫자 예제와 경계','0xB5=10110101₂는 1이 5개입니다. 전부 0인 N비트 값은 0, 전부 1이면 N입니다. 64비트 값 0x8000000100000001은 상위 32비트에 두 개, 하위에 한 개여서 합계 3입니다. 부호가 아니라 고정 폭 비트 패턴을 세는 함수입니다.'),
     ('CS 연결','SWAR는 한 정수 안의 작은 구획들을 마스크로 병렬 처리하는 기법입니다. 고정 폭 API는 고정 횟수 연산이며, 임의 길이 비트열 전체를 세려면 여러 워드를 처리해야 합니다. 곱셈을 사용한다고 항상 모든 CPU에서 더 빠르다고 가정하지 않고 설정별 구현을 나눈 이유를 봅니다.')],
    [('0xB5의 8비트 Hamming weight는?', '5', '4', '10110101의 1은 위치 7,5,4,2,0에 있어 다섯 개입니다. 숫자 크기나 로그 값과는 다른 측정입니다.'),
     ('BITS_PER_LONG==32에서 __sw_hweight64는 어떻게 합산하는가?', '상·하위 32비트의 __sw_hweight32 결과를 더한다', '상위 32비트를 버리고 하위만 센다', 'w>>32와 unsigned int 변환으로 나눈 두 조각을 각각 계산하여 더합니다. 전체 64비트를 빠짐없이 포함합니다.'),
     ('빠른 곱셈 경로가 꺼지면 계산 결과 정의가 바뀌는가?', '아니다. 같은 비트 수를 다른 연산 조합으로 계산한다', '그렇다. 절반의 비트만 센다', '설정은 구현 선택입니다. 이동·덧셈 경로와 곱셈 경로 모두 동일한 Hamming weight를 목표로 합니다.')])

add('lib/memweight.c','메모리 비트 수 전체: 정렬 전·워드 구간·마지막 바이트',
    '메모리 영역의 1비트 수를 셀 때 정렬과 바이트 순서를 고려해 처리 구간을 나눕니다.',
    'memweight는 먼저 unsigned long 크기 정렬에 도달할 때까지 바이트별 hweight8을 합칩니다. 남은 완전한 워드 수 longs를 구해 bitmap_weight로 한 번 처리한 뒤, 나머지 바이트를 다시 hweight8로 합칩니다.',
    '입력 ptr은 bytes만큼 읽을 수 있어야 하고 읽는 동안 안정적이어야 합니다. 중간 비트맵 처리량에는 INT_MAX/BITS_PER_LONG 조건을 검사하는 BUG_ON이 있어 임의로 큰 크기를 무조건 안전 처리한다고 가정하면 안 됩니다.',
    [('파일 전체','SPDX, export/bug/bitmap 헤더, 함수 하나와 EXPORT_SYMBOL이 전체입니다. ret 누적값·longs·바이트 포인터의 지역 상태만 사용하고 별도 메모리 할당은 없습니다. 시작 포인터의 주소를 sizeof(long)으로 나눈 나머지가 첫 루프의 정렬 조건입니다.'),
     ('세 구간 추적','sizeof(long)=8이고 시작 주소 오프셋이 3이며 길이 19라면 정렬까지 앞 5바이트를 처리합니다. 남은 14바이트 중 8바이트 한 워드를 bitmap_weight로 처리하고 꼬리 6바이트를 다시 처리합니다. 5+8+6=19이며 빠진 바이트나 중복 처리되는 바이트가 없어야 합니다.'),
     ('왜 꼬리는 따로 읽는가','원문은 big-endian 시스템에서 sizeof(long)보다 짧은 마지막 영역의 1비트를 올바르게 세기 위해 루프를 분리했다고 설명합니다. 완전한 워드와 달리 부분 바이트 영역을 워드 비트 번호 규칙에 그대로 넣으면 의미가 어긋날 수 있습니다. 바이트별 처리로 실제 남은 메모리 범위를 정확히 읽습니다.'),
     ('길이와 오류 계약','bytes=0이면 어느 루프도 메모리를 읽지 않고 0을 반환합니다. 완전 워드가 있으면 longs>=INT_MAX/BITS_PER_LONG을 BUG_ON으로 검사합니다. 이는 정상 오류 코드 반환이 아니며 nbits 인자로 전달할 곱의 범위를 지키려는 제한입니다. 호출자는 유효 메모리와 크기를 보장해야 합니다.'),
     ('CS 연결','정렬을 맞춰 큰 단위로 처리하고 앞뒤 경계를 작은 단위로 처리하는 peel/bulk/tail 패턴입니다. 전체 bytes에 선형인 작업이며 카운트를 구해도 입력의 동시 수정이 없는 스냅샷을 자동 보장하지 않습니다. ret가 size_t라는 것과 내부 bitmap_weight의 비트 수 인자 범위가 같다는 것도 아닙니다.')],
    [('8바이트 워드, 시작 오프셋 3, 길이 19의 세 구간 길이는?', '앞 5 + 중간 8 + 꼬리 6', '앞 3 + 중간 16 + 꼬리 0', '다음 정렬까지는 8-3=5바이트입니다. 남은 14에서 완전 워드 8을 처리하고 6바이트가 남습니다.'),
     ('마지막 바이트 루프를 별도로 두는 원문 이유는?', 'big-endian에서도 부분 워드 영역의 실제 바이트를 올바르게 세려고', '마지막 바이트는 모두 0이라고 가정하려고', '꼬리는 sizeof(long)보다 작으므로 메모리 범위와 워드 비트 번호 해석을 혼동하지 않도록 바이트 단위로 계산합니다.'),
     ('bytes=0에서 반환값은?', '0이며 입력 바이트를 읽지 않는다', '반드시 한 바이트를 읽어 비트 수를 반환한다', '앞·뒤 루프 조건은 bytes>0이고 longs도 0입니다. 누적 ret 초기값 0을 그대로 반환합니다.')])
